<script setup lang="ts">
import { computed, onMounted, reactive, ref } from "vue";
import { Building, ExternalLink, KeyRound, LockKeyhole, Plus, ShieldCheck, UserRound } from "lucide-vue-next";

import ModalPanel from "../components/ModalPanel.vue";
import PageHeader from "../components/PageHeader.vue";
import StatusBadge from "../components/StatusBadge.vue";
import { api, type Account, type Asset, type AssetType, type CredentialReference, type LegalEntity, type Platform, type PlatformTenant, type Provider } from "../lib/api";

const tab = ref<"platforms" | "tenants" | "accounts">("tenants"); const modal = ref<"platform" | "tenant" | "account" | "credential" | null>(null); const saving = ref(false); const error = ref("");
const providers = ref<Provider[]>([]); const platforms = ref<Platform[]>([]); const tenants = ref<PlatformTenant[]>([]); const accounts = ref<Account[]>([]); const credentials = ref<CredentialReference[]>([]); const assets = ref<Asset[]>([]); const types = ref<AssetType[]>([]); const entities = ref<LegalEntity[]>([]); const credentialAccount = ref("");
const platformForm = reactive({ provider_id: "", provider_code: "", provider_name: "", code: "", name: "", category: "cloud", website: "" });
const tenantForm = reactive({ platform_id: "", legal_entity_id: "", tenant_identifier: "", asset_name: "", owner_department_id: null });
const accountForm = reactive({ platform_tenant_id: "", legal_entity_id: "", asset_name: "", login_identifier: "", account_type: "company_primary", registration_identity_type: "company", mfa_status: "unknown", privilege_level: "normal" });
const credentialForm = reactive({ provider: "bitwarden", item_id: "", secure_url: "" });
const assetName = computed(() => Object.fromEntries(assets.value.map((item) => [item.id, item.name]))); const platformName = computed(() => Object.fromEntries(platforms.value.map((item) => [item.id, item.name]))); const tenantName = computed(() => Object.fromEntries(tenants.value.map((item) => [item.id, item.tenant_identifier])));
const tenantType = computed(() => types.value.find((item) => item.code === "platform_tenant")); const accountType = computed(() => types.value.find((item) => item.code === "platform_account"));
async function load() { try { const [providerRows, platformRows, tenantRows, accountRows, credentialRows, assetRows, typeRows, entityRows] = await Promise.all([api.providers(), api.platforms(), api.platformTenants(), api.accounts(), api.credentialReferences(), api.assets(), api.assetTypes(), api.legalEntities()]); providers.value = providerRows; platforms.value = platformRows; tenants.value = tenantRows; accounts.value = accountRows; credentials.value = credentialRows; assets.value = assetRows.data; types.value = typeRows; entities.value = entityRows; tenantForm.platform_id ||= platforms.value[0]?.id ?? ""; tenantForm.legal_entity_id ||= entities.value[0]?.id ?? ""; accountForm.platform_tenant_id ||= tenants.value[0]?.id ?? ""; accountForm.legal_entity_id ||= entities.value[0]?.id ?? "" } catch (reason) { error.value = reason instanceof Error ? reason.message : "加载失败" } }
async function save() {
  saving.value = true; error.value = "";
  try {
    if (modal.value === "platform") {
      let providerId = platformForm.provider_id;
      if (!providerId) { const provider = await api.createProvider({ code: platformForm.provider_code, name: platformForm.provider_name }); providerId = provider.id }
      await api.createPlatform({ provider_id: providerId, code: platformForm.code, name: platformForm.name, category: platformForm.category, website: platformForm.website || null });
    }
    if (modal.value === "tenant") {
      if (!tenantType.value) throw new Error("平台租户资产类型未初始化");
      const asset = await api.createAsset({ name: tenantForm.asset_name, asset_type_id: tenantType.value.id, legal_entity_id: tenantForm.legal_entity_id, status: "active", criticality: "important" });
      await api.createPlatformTenant({ asset_id: asset.id, platform_id: tenantForm.platform_id, legal_entity_id: tenantForm.legal_entity_id, tenant_identifier: tenantForm.tenant_identifier });
    }
    if (modal.value === "account") {
      if (!accountType.value) throw new Error("平台账号资产类型未初始化");
      const asset = await api.createAsset({ name: accountForm.asset_name, asset_type_id: accountType.value.id, legal_entity_id: accountForm.legal_entity_id, status: "active", criticality: accountForm.privilege_level === "admin" ? "critical" : "important", confidentiality: "sensitive" });
      await api.createAccount({ asset_id: asset.id, platform_tenant_id: accountForm.platform_tenant_id, login_identifier: accountForm.login_identifier, account_type: accountForm.account_type, registration_identity_type: accountForm.registration_identity_type, mfa_status: accountForm.mfa_status, privilege_level: accountForm.privilege_level });
    }
    if (modal.value === "credential") await api.createCredentialReference({ account_id: credentialAccount.value, provider: credentialForm.provider, item_id: credentialForm.item_id, secure_url: credentialForm.secure_url || null });
    modal.value = null; await load();
  } catch (reason) { error.value = reason instanceof Error ? reason.message : "保存失败" }
  finally { saving.value = false }
}
function openCredential(accountId: string) { credentialAccount.value = accountId; modal.value = "credential" }
onMounted(load);
</script>

<template>
  <div class="page-stack">
    <PageHeader eyebrow="控制入口" title="平台与账号" description="先看公司使用了哪些平台，再进入具体公司账号、访问账号和人员授权。"><RouterLink class="secondary-button" to="/intake"><Plus :size="16" />提交新平台</RouterLink><RouterLink class="primary-button" to="/intake"><Plus :size="16" />登记平台账号</RouterLink></PageHeader>
    <div v-if="error" class="message-panel error-message">{{ error }}</div>
    <div class="dimension-tabs"><button :class="{ active: tab === 'tenants' }" @click="tab = 'tenants'">公司平台账号 {{ tenants.length }}</button><button :class="{ active: tab === 'accounts' }" @click="tab = 'accounts'">访问账号与授权 {{ accounts.length }}</button><button :class="{ active: tab === 'platforms' }" @click="tab = 'platforms'">平台目录 {{ platforms.length }}</button></div>
    <section class="content-panel accounts-panel">
      <div v-if="tab === 'accounts'" class="account-grid"><article v-for="item in accounts" :key="item.id"><header><span class="record-icon"><UserRound :size="19" /></span><div><strong>{{ assetName[item.asset_id] ?? item.login_identifier }}</strong><span>{{ item.login_identifier }}</span></div><StatusBadge tone="success">{{ item.account_role || item.privilege_level }}</StatusBadge></header><dl><div><dt>所属公司账号</dt><dd>{{ tenantName[item.platform_tenant_id] || '未命名账号' }}</dd></div><div><dt>访问账号类型</dt><dd>{{ item.account_kind || item.account_type }}</dd></div><div><dt>登录方式</dt><dd>{{ item.login_method || item.registration_identity_type }}</dd></div><div><dt>权限角色</dt><dd>{{ item.account_role || item.privilege_level }}</dd></div></dl><footer><div v-if="credentials.find((row) => row.account_id === item.id)" class="credential-link"><LockKeyhole :size="15" /><span>凭据已登记</span><a v-if="credentials.find((row) => row.account_id === item.id)?.secure_url" :href="credentials.find((row) => row.account_id === item.id)?.secure_url ?? ''" target="_blank"><ExternalLink :size="14" /></a></div><button v-else class="secondary-button" @click="openCredential(item.id)"><KeyRound :size="14" />登记凭据状态</button></footer></article><div v-if="!accounts.length" class="large-empty-panel"><KeyRound :size="28" /><strong>尚未登记访问账号</strong><p>简单平台可以没有这一层；阿里云 RAM、工具子账号和员工席位在这里管理。</p></div></div>
      <div v-if="tab === 'tenants'" class="record-list"><div v-for="item in tenants" :key="item.id"><span class="record-icon"><Building :size="18" /></span><div><strong>{{ assetName[item.asset_id] ?? '未命名公司账号' }}</strong><span>{{ platformName[item.platform_id] }} · {{ item.tenant_identifier ? `平台 ID ${item.tenant_identifier}` : '未提供平台 UID' }}</span></div><StatusBadge :tone="item.verification_status === 'verified' ? 'success' : 'warning'">{{ item.verification_status === 'verified' ? '已核验' : '待核验' }}</StatusBadge></div><div v-if="!tenants.length" class="mini-empty">尚未登记公司平台账号</div></div>
      <div v-if="tab === 'platforms'" class="card-grid"><article v-for="item in platforms" :key="item.id" class="entity-card"><span class="record-icon"><ShieldCheck :size="20" /></span><div><strong>{{ item.name }}</strong><span>平台</span><small>{{ tenants.filter((row) => row.platform_id === item.id).length }} 个公司账号</small></div><StatusBadge :tone="item.review_status === 'approved' ? 'success' : 'warning'">{{ item.review_status === 'approved' ? '已标准化' : '待审核' }}</StatusBadge><a v-if="item.website" :href="item.website" target="_blank" class="icon-button"><ExternalLink :size="16" /></a></article><div v-if="!platforms.length" class="mini-empty">尚未建立平台目录</div></div>
    </section>
    <ModalPanel v-if="modal" :title="modal === 'platform' ? '新增平台目录' : modal === 'tenant' ? '登记企业租户' : modal === 'account' ? '登记平台账号' : '添加密码库引用'" @close="modal = null"><form class="form-grid one-column" @submit.prevent="save"><template v-if="modal === 'platform'"><label><span>已有供应商</span><select v-model="platformForm.provider_id"><option value="">同时新建供应商</option><option v-for="item in providers" :key="item.id" :value="item.id">{{ item.name }}</option></select></label><template v-if="!platformForm.provider_id"><label><span>供应商编码 *</span><input v-model="platformForm.provider_code" required /></label><label><span>供应商名称 *</span><input v-model="platformForm.provider_name" required /></label></template><label><span>平台编码 *</span><input v-model="platformForm.code" required /></label><label><span>平台名称 *</span><input v-model="platformForm.name" required /></label><label><span>平台分类</span><input v-model="platformForm.category" /></label><label><span>官网</span><input v-model="platformForm.website" /></label></template><template v-if="modal === 'tenant'"><label><span>平台 *</span><select v-model="tenantForm.platform_id" required><option v-for="item in platforms" :key="item.id" :value="item.id">{{ item.name }}</option></select></label><label><span>所有权公司 *</span><select v-model="tenantForm.legal_entity_id" required><option v-for="item in entities" :key="item.id" :value="item.id">{{ item.name }}</option></select></label><label><span>资产名称 *</span><input v-model="tenantForm.asset_name" required placeholder="例如：阿里云集团主租户" /></label><label><span>平台租户标识 *</span><input v-model="tenantForm.tenant_identifier" required placeholder="UID、企业ID或组织名" /></label></template><template v-if="modal === 'account'"><label><span>所属平台租户 *</span><select v-model="accountForm.platform_tenant_id" required><option v-for="item in tenants" :key="item.id" :value="item.id">{{ platformName[item.platform_id] }} / {{ item.tenant_identifier }}</option></select></label><label><span>所有权公司 *</span><select v-model="accountForm.legal_entity_id" required><option v-for="item in entities" :key="item.id" :value="item.id">{{ item.name }}</option></select></label><label><span>资产名称 *</span><input v-model="accountForm.asset_name" required placeholder="例如：阿里云主账号" /></label><label><span>登录标识 *</span><input v-model="accountForm.login_identifier" required placeholder="邮箱、手机号或用户名；不填写密码" /></label><label><span>账号类型</span><select v-model="accountForm.account_type"><option value="company_primary">公司主账号</option><option value="personal_work">个人实名工作账号</option><option value="shared_business">共享业务账号</option><option value="admin">管理员/根账号</option><option value="programmatic">程序/API账号</option><option value="external">外部合作方账号</option></select></label><label><span>MFA状态</span><select v-model="accountForm.mfa_status"><option value="unknown">未知</option><option value="enabled">已开启</option><option value="disabled">未开启</option><option value="not_applicable">不适用</option></select></label><label><span>权限级别</span><select v-model="accountForm.privilege_level"><option value="normal">普通</option><option value="sensitive">敏感</option><option value="admin">管理员</option><option value="root">根权限</option></select></label></template><template v-if="modal === 'credential'"><div class="form-hint">只保存外部密码库条目ID或安全链接，禁止填写密码、Secret、私钥和恢复码。</div><label><span>密码库产品</span><select v-model="credentialForm.provider"><option value="bitwarden">Bitwarden</option><option value="1password">1Password</option><option value="keeper">Keeper</option><option value="other">其他</option></select></label><label><span>条目ID *</span><input v-model="credentialForm.item_id" required /></label><label><span>安全跳转链接</span><input v-model="credentialForm.secure_url" /></label></template><div class="form-actions"><button type="button" class="secondary-button" @click="modal = null">取消</button><button class="primary-button" :disabled="saving">保存</button></div></form></ModalPanel>
  </div>
</template>
